from fastapi import FastAPI, HTTPException
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field


class Product(BaseModel):
    name: str
    price: float = Field(..., gt=0)


class LooseProduct(BaseModel):
    name: str
    price: float


def make_shop_app(variant):
    """Магазин; в вариантах no404, no422, wrong_code спрятана одна ошибка, в варианте ok её нет."""
    app = FastAPI()
    items = {}
    model = LooseProduct if variant == "no422" else Product
    created = 200 if variant == "wrong_code" else 201

    @app.post("/products", status_code=created)
    def create(product: model):
        items[len(items) + 1] = product.dict()
        return {"id": len(items), **product.dict()}

    @app.get("/products/{product_id}")
    def read(product_id: int):
        if product_id not in items:
            if variant == "no404":
                return {"detail": "нет такого"}
            raise HTTPException(status_code=404, detail="Товар не найден")
        return {"id": product_id, **items[product_id]}

    return app


def check(variant):
    client = TestClient(make_shop_app(variant))
    try:
        assert client.post("/products", json={"name": "Чай", "price": 5}).status_code == 201
        assert client.get("/products/1").status_code == 200
        assert client.get("/products/99").status_code == 404
        assert client.post("/products", json={"name": "Яд", "price": -1}).status_code == 422
    except AssertionError:
        return False
    return True

